SELECT 
FROM todo_items t LEFT JOIN projects p ON p.id = t.project_id
WHERE t.id = #{id}

SELECT 
FROM todo_items t LEFT JOIN projects p ON p.id = t.project_id

    AND t.status = #{status}
    AND t.project_id IS NULL
    AND t.project_id = #{projectId}
    AND t.priority = #{priority}
    AND t.due_at < #{now} AND t.status = 'PENDING'
    AND t.due_at >= #{todayStart} AND t.due_at < #{tomorrowStart}
    AND t.due_at >= #{tomorrowStart}
    AND t.due_at IS NULL

ORDER BY CASE t.status WHEN 'PENDING' THEN 0 ELSE 1 END,
         t.due_at ASC NULLS LAST,
         CASE t.priority WHEN 'HIGH' THEN 0 WHEN 'MEDIUM' THEN 1 ELSE 2 END,
         t.created_at DESC
